<script setup lang="ts">
import BusinessTabs from './components/BusinessTabs.vue'
import CountrySelect from './components/CountrySelect.vue'
import PriceReferenceModal from './components/PriceReferenceModal.vue'
import {emptyPrices,rankCountries,type PriceData} from './priceReference'
import PartnerPage from './components/PartnerPage.vue'
import {useOrderUpdates,serialRefresh,orderConnection} from './orderUpdates'
import {ref,onMounted,onUnmounted,computed,watch} from 'vue'
import {ArrowRight,ArrowUpRight,Wallet,ReceiptText,ShieldCheck,Plus,Copy,KeyRound,Gift,Check,Clock3,LockKeyhole,Layers3,Link2,Sparkles,Bell,Settings2,TrendingUp,ExternalLink,Download} from 'lucide-vue-next'
import {api,action,cash,date,labels,orderLabel,orderTone,renewalAttention,notify,copy,key,type Row} from './lib'
import DataTable from './components/DataTable.vue'
import OrderCenter from './components/OrderCenter.vue'
import LedgerTable from './components/LedgerTable.vue'
import RechargeTable from './components/RechargeTable.vue'
import Modal from './components/Modal.vue'
import ProgressTrack from './components/ProgressTrack.vue'
import MembershipPage from './components/MembershipPage.vue'
import ProfilePage from './components/ProfilePage.vue'
import RenewalPage from './components/RenewalPage.vue'
import CheckoutResult from './components/CheckoutResult.vue'
import PaymentPanel from './components/PaymentPanel.vue'
import {parseCardLine} from './card-line'
import {featureAllowed} from './featureAccess'
const origin=location.origin
const props=defineProps<{route:string;search?:string;user:Row;pub:Row;business?:string}>();const emit=defineEmits<{refresh:[];logout:[];business:[value:'subscription'|'registration'|'refund']}>()
const enabled=(name:string)=>featureAllowed(props.user.features,name)
const loading=ref(true)
const data=ref<Row>({}),items=ref<Row[]>([]),busy=ref(false),error=ref(''),modal=ref(''),detail=ref<Row>({}),keyName=ref(''),newKey=ref(''),redeem=ref(''),topupAmount=ref(100),proof=ref(''),tab=ref('ledger')
const product=ref('pro'),country=ref(''),seats=ref(2),sessionText=ref(''),sessionInfo=ref<Row|null>(null),sessionError=ref(''),checking=ref(false),accepted=ref(false),renew=ref(false)
const cardLine=ref(''),cardTouched=ref(false)
const parsedCard=computed(()=>parseCardLine(cardLine.value,new Date(now.value)))
const subscriptionRegions=computed<Row[]>(()=>props.pub.countries||[])
watch(subscriptionRegions,rows=>{if(country.value&&!rows.some(r=>r.code===country.value)){country.value='';accepted.value=false}},{immediate:true})
const subscriptionCurrency=computed(()=>subscriptionRegions.value.find(r=>r.code===country.value)?.currency||'')
const fullSubscription=computed(()=>props.route==='/subscribe')
const serviceConnected=computed(()=>fullSubscription.value?props.pub.payment_connected===true:props.pub.checkout_connected===true)
const cardReady=computed(()=>!!parsedCard.value.card)
function clearCard(){cardLine.value='';cardTouched.value=false}
onUnmounted(clearCard)
watch(country,()=>{accepted.value=false})
const premiumSeats=ref(0),promoCode=ref(''),detailRefreshError=ref('')
const selected=computed(()=>props.pub.products.find((p:Row)=>p.id===product.value)||props.pub.products[0])
const isTeam=computed(()=>selected.value?.id?.startsWith('team'))
const unifiedTeam=computed(()=>isTeam.value&&props.pub.subscription_flow==='cslive_go_direct_pay')
const teamTotal=computed(()=>unifiedTeam.value?Number(seats.value)+Number(premiumSeats.value):Number(seats.value))
const priceReference=ref<PriceData>(emptyPrices()),priceLoading=ref(false),priceError=ref('')
const pricedCountries=computed(()=>rankCountries(subscriptionRegions.value as (Row&{code:string;currency:string})[],priceReference.value,selected.value?.id||'',unifiedTeam.value?Number(seats.value):Number(seats.value)-Number(premiumSeats.value),Number(premiumSeats.value)))
async function loadPriceReference(){if(priceLoading.value)return;priceLoading.value=true;priceError.value='';try{priceReference.value=await api('/subscription-prices')}catch(e){priceError.value=(e as Error).message}finally{priceLoading.value=false}}
watch(()=>props.route,value=>{if(['/subscribe','/links'].includes(value))void loadPriceReference()},{immediate:true})
const teamError=computed(()=>!isTeam.value?'':!Number.isInteger(seats.value)||!Number.isInteger(premiumSeats.value)||seats.value<0||premiumSeats.value<0||teamTotal.value<2||teamTotal.value>100||(!unifiedTeam.value&&premiumSeats.value>seats.value)?'普通与高级席位合计须为 2～100 席，请填写整数。':'')
const chosenRegion=computed(()=>subscriptionRegions.value.find(r=>r.code===country.value))
const availableBalance=computed(()=>Number(props.user.balance||0)-Number(props.user.frozen||0))
watch(selected,()=>{premiumSeats.value=unifiedTeam.value?0:1;seats.value=2;promoCode.value='';accepted.value=false})
watch([seats,premiumSeats,promoCode],()=>{accepted.value=false})
const quotedFee=ref<number|null>(null),quoteInfo=ref<Row>({}),quoteError=ref(''),quoting=ref(false)
let quoteRevision=0,quoteController:AbortController|undefined
async function loadQuote(){
 const revision=++quoteRevision;quoteController?.abort();quotedFee.value=null;quoteInfo.value={};quoteError.value='';quoting.value=false
 if(!selected.value||!['/subscribe','/links'].includes(props.route))return
 const controller=new AbortController();quoteController=controller;quoting.value=true
 const timeout=setTimeout(()=>controller.abort(),15000)
 try{const result=await api('/quote?product_id='+encodeURIComponent(selected.value.id),'GET',undefined,{},controller.signal);if(revision===quoteRevision){quotedFee.value=result.fee;quoteInfo.value=result}}
 catch{if(revision===quoteRevision)quoteError.value='服务费报价暂时无法获取，请重试。'}
 finally{clearTimeout(timeout);if(revision===quoteRevision)quoting.value=false}
}
watch([selected,()=>JSON.stringify([props.user.membership?.service_prices,props.user.membership?.product_prices,props.user.membership?.discount_services]),()=>props.user.fee_override,()=>props.user.membership?.current?.code,()=>props.user.membership?.current?.discount],loadQuote,{immediate:true})
let sessionTimer:ReturnType<typeof setTimeout>,sessionRevision=0,sessionController:AbortController|undefined
const now=ref(Date.now()),sessionExpired=computed(()=>!!sessionInfo.value&&new Date(sessionInfo.value.expires_at).getTime()<=now.value)
const sessionPlan=computed(()=>(({free:'免费方案',plus:'Plus',pro:'Pro',team:'Team 团队',business:'Business 团队',enterprise:'企业方案'} as Record<string,string>)[sessionInfo.value?.plan as string]||'账号方案未标注'))
const canSave=computed(()=>!teamError.value&&subscriptionRegions.value.some(r=>r.code===country.value)&&!busy.value&&!!selected.value&&!!sessionInfo.value&&!checking.value&&!sessionExpired.value&&quotedFee.value!==null&&accepted.value)
async function inspect(){
 clearTimeout(sessionTimer);const revision=++sessionRevision;sessionController?.abort();sessionInfo.value=null;sessionError.value='';checking.value=false
 if(!sessionText.value.trim())return
 const controller=new AbortController();sessionController=controller;checking.value=true
 const timeout=setTimeout(()=>controller.abort(),15000)
 try{let session=JSON.parse(sessionText.value);if(typeof session==='string')session=JSON.parse(session);const result=await api('/session/inspect','POST',{session,workflow:fullSubscription.value?'subscription':'checkout'},{},controller.signal);if(revision===sessionRevision){now.value=Date.now();sessionInfo.value=result}}
 catch(e){if(revision===sessionRevision)sessionError.value=controller.signal.aborted?'检查超时，请重新检查。':e instanceof SyntaxError?'请输入完整、有效的 Session JSON':(e as Error).message}
 finally{clearTimeout(timeout);if(revision===sessionRevision)checking.value=false}
}
watch(sessionText,()=>{sessionRevision++;sessionController?.abort();sessionInfo.value=null;sessionError.value='';checking.value=false;clearTimeout(sessionTimer);if(sessionText.value.trim())sessionTimer=setTimeout(inspect,600)})
let expiryTimer:ReturnType<typeof setInterval>|undefined
onMounted(()=>{if(['/subscribe','/links'].includes(props.route))expiryTimer=setInterval(()=>{now.value=Date.now()},1000)})
onUnmounted(()=>{clearInterval(expiryTimer);clearTimeout(sessionTimer);sessionRevision++;quoteRevision++;sessionController?.abort();quoteController?.abort()})
const draftKey=ref(key());const inviteURL=computed(()=>`${location.origin}/?invite=${props.user.invite_code}`)
const routeParams=new URLSearchParams(props.search||'')
const orderFilter=ref({q:routeParams.get('order_id')||'',status:routeParams.get('status')||'',attention:routeParams.get('attention')||''})
const orderQuery=()=>new URLSearchParams(orderFilter.value).toString()
async function load(){loading.value=true;error.value='';try{if(props.route==='/orders')items.value=(await api('/orders?'+orderQuery())).items;else if(props.route==='/wallet')data.value=await api('/wallet');else if(props.route==='/keys')items.value=(await api('/keys')).items;}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
async function submit(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;await action(fn);busy.value=false}
async function showOrder(r:Row){await action(async()=>{detail.value=await api('/orders/'+r.id);modal.value='order'})}
async function cancelOrder(id:string){await submit(async()=>{await api('/orders/'+id+'/cancel','POST',{});notify('申请已结束；已复制的链接不会因此在上游失效');modal.value='';await load()})}
async function createDraft(prepare=false){
 now.value=Date.now();if(!canSave.value||(prepare&&!serviceConnected.value))return
 const full=prepare&&fullSubscription.value
 if(full&&!cardReady.value)return
 await submit(async()=>{
  let v
  try{const flowPrefix=props.pub?.subscription_flow==='cslive_full_go'?'/cslive-full':props.pub?.subscription_flow==='cslive_go_direct_pay'?'/cslive-go':'';v=await api(flowPrefix+'/orders','POST',{product_id:selected.value.id,session:JSON.parse(sessionText.value),country:country.value,seats:isTeam.value?teamTotal.value:1,accepted:accepted.value,...(isTeam.value?{premium_seats:premiumSeats.value}:{}),...(unifiedTeam.value&&promoCode.value.trim()?{promo_code:promoCode.value.trim()}:{}),...(prepare?{prepare:true}:{}),...(full?{workflow:'subscription',keep_renewal:renew.value,card:parsedCard.value.card}:{})},{'Idempotency-Key':draftKey.value})}finally{if(full)clearCard()}
  draftKey.value=key();sessionText.value='';if(enabled('orders')){detail.value=await api('/orders/'+v.id);modal.value='order'}emit('refresh');notify(full?'已受理，将自动办理付款及续费设置':prepare?'已提交结账准备；未付款或扣费':'已保存方案；未提交付款或扣费')
 })
}
const updateList=serialRefresh(load)
const updateDetail=serialRefresh(async()=>{const id=detail.value.order?.id;if(modal.value!=='order'||!id)return;try{const v=await api('/orders/'+id,'GET',undefined,{},AbortSignal.timeout(10000));if(modal.value==='order'&&detail.value.order?.id===id){detail.value=v;detailRefreshError.value=''}}catch{detailRefreshError.value='进度更新暂时失败，请点击刷新重试。'}})
useOrderUpdates(id=>{if(modal.value==='order'&&(!id||detail.value.order?.id===id))void updateDetail();else if(!busy.value&&!modal.value&&['/orders','/wallet'].includes(props.route))void updateList()},{enabled:()=>enabled('orders')})
onMounted(async()=>{await load();const id=routeParams.get('order_id');if(props.route==='/orders'&&id)await showOrder({id})})
</script>
<template><div class="customer-content" :aria-busy="loading"><div v-if="error" class="alert danger">{{error}}<button @click="load">重试</button></div>
<MembershipPage v-if="route==='/membership'"/><template v-else-if="route==='/subscribe'||route==='/links'"><div class="page-heading"><div><span class="eyebrow">BUILD YOUR NEXT SUBSCRIPTION</span><h1>为下一步，选好服务。</h1><p>选择套餐与地区，清楚了解费用后再开始。</p></div><span class="pill amber"><Clock3 :size="14"/>{{fullSubscription?'提交一次 · 连续办理':'仅生成结账链接'}}</span></div><div class="subscription-price-toolbar"><PriceReferenceModal :data="priceReference" :initial-plan="selected?.id||'plus'" :selected-country="country" :loading="priceLoading" :error="priceError" @refresh="loadPriceReference"/></div><div class="product-picker"><button v-for="p in pub.products" :key="p.id" :aria-pressed="selected?.id===p.id" :class="{selected:selected?.id===p.id}" @click="product=p.id"><span>{{p.tag}}</span><h3>{{p.name}}</h3><p>{{p.description}}</p><div><b>{{cash(p.fee)}}<small>积分 / 次</small></b><span class="select-ring"><Check v-if="selected?.id===p.id" :size="15"/></span></div></button></div>
<form class="checkout-grid subscription-layout" :class="{'subscription-form':fullSubscription}" autocomplete="off" @submit.prevent="createDraft(true)">
  <section class="panel form-panel subscription-config">
    <div class="panel-heading"><h2>配置订阅</h2><span>{{selected?.name}}</span></div>
    <section class="subscription-step"><div class="step-caption"><span class="number-box">01</span><div><h3>支付国家 / 地区</h3><p>选择本次订阅的结算地区与币种。</p></div></div><div class="step-fields"><CountrySelect v-model="country" :countries="pricedCountries" show-prices :price-loading="priceLoading"/><small class="country-price-hint">按当前套餐的 R 参考价排序；税费、优惠以实际结账为准。<template v-if="isTeam">按当前席位数量估算。</template><template v-if="priceError">参考价格暂不可用。</template></small></div></section>
    <section v-if="isTeam" class="subscription-step"><div class="step-caption"><span class="number-box">02</span><div><h3>Team 配置</h3><p>普通与高级席位合计至少 2 席。</p></div></div><div class="step-fields"><div class="form-grid"><label>{{unifiedTeam?'普通席位':'总席位'}}<input v-model.number="seats" type="number" :min="unifiedTeam?0:2" max="100" step="1" required/></label><label>高级席位<input v-model.number="premiumSeats" type="number" :min="unifiedTeam?0:1" max="100" step="1" required/></label></div><p class="team-seat-total" :class="{'danger-text':teamError}" role="status">{{teamError||'合计 '+teamTotal+' 席 · 普通 '+(unifiedTeam?seats:seats-premiumSeats)+' 席 / 高级 '+premiumSeats+' 席'}}</p><label v-if="unifiedTeam" class="team-promo">自定义优惠码（可选）<input v-model="promoCode" maxlength="256" placeholder="填写你自己的 Team 优惠码" autocomplete="off" spellcheck="false"/><small>留空则不使用优惠码；是否适用及实际优惠金额以上游结账结果为准。</small></label></div></section>
    <section class="subscription-step"><div class="step-caption"><span class="number-box">{{isTeam?'03':'02'}}</span><div><h3>填写 Session</h3><p>粘贴完整 Session JSON，自动识别目标账号。</p></div></div><div class="step-fields"><label>账号 Session<textarea v-model="sessionText" :rows="fullSubscription?5:6" required maxlength="262144" autocomplete="off" spellcheck="false" placeholder="粘贴完整 Session JSON，自动识别订阅账号，无需手填邮箱。"></textarea><small>{{fullSubscription?'需包含 sessionToken 或会话 Cookie。':''}}所需令牌加密暂存，办理结束或到期后清除。</small></label><p v-if="checking" class="muted">正在识别账号…</p><div v-if="sessionError" class="alert danger" role="alert"><span>{{sessionError}}</span><button type="button" class="text-btn" @click="inspect" :disabled="checking">重新检查</button></div><div v-if="sessionExpired" class="alert danger" role="alert">Session 已过期，请重新获取</div><div v-if="sessionInfo&&!sessionExpired" class="session-result"><ShieldCheck :size="20"/><div><b>{{sessionInfo.email}}</b><p>有效期内 · {{sessionPlan}} · 到期 {{date(sessionInfo.expires_at)}}</p><small>格式检查通过，尚未核验在线状态</small></div><button type="button" class="text-btn" @click="inspect">重新检查</button></div></div></section>
    <section v-if="fullSubscription" class="subscription-step"><div class="step-caption"><span class="number-box">{{isTeam?'04':'03'}}</span><div><h3>付款卡片</h3><p>整行粘贴，自动识别卡片格式。</p></div></div><div class="step-fields subscription-payment"><label for="subscription-card-line">卡片信息<textarea id="subscription-card-line" name="subscription-card-line" v-model="cardLine" rows="2" maxlength="120" required autocomplete="off" autocapitalize="off" spellcheck="false" data-lpignore="true" data-1p-ignore="true" placeholder="卡号----MM/YY----CVV" aria-describedby="card-line-help" @blur="cardTouched=true"></textarea><small id="card-line-help">支持 卡号----MM/YY----CVV 或 卡号|MM|YYYY|CVV。仅使用本人或已获授权的银行卡。</small></label><p v-if="cardTouched&&parsedCard.error" class="card-line-error" role="alert">{{parsedCard.error}}</p><div v-if="parsedCard.card" class="card-line-ready" role="status"><ShieldCheck :size="16"/><span>格式已识别 · 尾号 {{parsedCard.card.number.slice(-4)}} · 有效期 {{parsedCard.card.month}}/{{parsedCard.card.year}}</span><button type="button" class="text-btn" @click="clearCard">清空</button></div></div></section>
    <section v-else class="subscription-step"><div class="step-caption"><Link2 :size="18"/><div><h3>链接生成</h3></div></div><div class="step-fields"><p>仅生成结账链接，链接类型由平台配置。生成后本次任务即完成，可复制链接或在新窗口打开。</p><p class="small muted">仅提链不冻结或收取服务费。</p></div></section>
  </section>
  <aside class="order-summary subscription-confirmation"><div class="confirmation-heading"><h2>订单确认</h2><span>{{fullSubscription?'自备卡支付':'仅生成链接'}}</span></div><div class="confirmation-plan"><Layers3 :size="26"/><div><h3>{{selected?.name}}</h3><p>{{chosenRegion?chosenRegion.name+' / '+subscriptionCurrency:'请选择支付国家 / 地区'}}</p></div></div><div class="summary-total"><span>{{fullSubscription?'本次服务费':'本次结账准备'}}</span><strong>{{fullSubscription?(quotedFee==null?'—':cash(quotedFee)):'0.00'}}<small>积分</small></strong><p>{{fullSubscription?'平台服务费，上游订阅费用按实时含税金额另行结算。':'仅生成结账链接，不扣款或冻结余额。'}}</p></div><div class="summary-line"><span>目标账号</span><b class="summary-account">{{sessionInfo?.email||'待填写'}}</b></div><div v-if="isTeam" class="summary-line"><span>席位配置</span><b>普通 {{unifiedTeam?seats:seats-premiumSeats}} / 高级 {{premiumSeats}} · 合计 {{teamTotal}}</b></div><div v-if="unifiedTeam" class="summary-line"><span>自定义优惠码</span><b>{{promoCode.trim()?'已填写':'不使用'}}</b></div><div class="summary-line"><span>标准服务费</span><b>{{cash(selected?.fee)}} 积分</b></div><div v-if="['product_override','account_override'].includes(quoteInfo.price_source)" class="summary-line"><span>专属价格</span><b>{{cash(quotedFee)}} 积分</b></div><div v-else-if="quoteInfo.membership&&quoteInfo.membership_eligible!==false" class="summary-line"><span>{{quoteInfo.membership.current.name}}</span><b>减免 {{100-quoteInfo.membership.current.discount}}%</b></div><div v-if="quoteInfo.membership_eligible===false" class="summary-line"><span>会员减免</span><b>此服务不参与会员减免</b></div><div class="summary-line"><span>服务费报价</span><b>{{quotedFee==null?(quoting?'正在获取…':'—'):cash(quotedFee)+' 积分'}}</b></div><div v-if="quoteError" class="alert danger quote-error" role="alert">{{quoteError}}<button type="button" class="text-btn" @click="loadQuote" :disabled="quoting">重新获取报价</button></div><div v-if="enabled('wallet')" class="summary-line"><span>可用积分</span><b>{{cash(availableBalance)}} 积分</b></div><div v-if="enabled('wallet')&&quotedFee!=null" class="summary-line"><span>办理后余额</span><b :class="{'danger-text':fullSubscription&&availableBalance<quotedFee}">{{cash(availableBalance-(fullSubscription?quotedFee:0))}} 积分</b></div>
    <section v-if="fullSubscription" class="confirmation-renewal">
      <fieldset class="renewal-fieldset"><legend>自动续费</legend><div class="renewal-options">
        <label class="renewal-option" :class="{selected:!renew}"><input v-model="renew" type="radio" name="subscription-renewal" :value="false" aria-describedby="renewal-explanation"/><span>支付后关闭</span></label>
        <label class="renewal-option" :class="{selected:renew}"><input v-model="renew" type="radio" name="subscription-renewal" :value="true" aria-describedby="renewal-explanation"/><span>保留自动续费</span></label>
      </div></fieldset>
      <p id="renewal-explanation">{{renew?'到期后将按上游规则自动续费。':'付款后关闭自动续费，已购买的有效期不变。'}}</p>
    </section>
    <label class="confirmation-consent" :class="{accepted}"><input type="checkbox" v-model="accepted" required/><span>{{fullSubscription?'我授权按实时含税金额付款，并同意上述续费设置及':'我已阅读并同意'}}<a href="https://openai.com/zh-Hans-CN/policies/terms-of-use/" target="_blank" rel="noopener noreferrer" @click.stop>《服务约定》</a>。</span></label>
    <p v-if="!serviceConnected" class="muted small" role="status">{{fullSubscription?'订阅办理暂未开放。':'结账链接暂未开放。'}}</p>
    <button type="submit" class="btn primary full" :disabled="!canSave||!serviceConnected||(fullSubscription&&!cardReady)">{{busy?'提交中…':fullSubscription?'开始订阅办理':'生成结账链接'}}<ArrowRight :size="17"/></button><button type="button" class="btn secondary full" :disabled="!canSave" @click="createDraft(false)">保存订阅方案</button></aside>
</form></template>
<OrderCenter :can-subscribe="enabled('subscribe')" :initial-filter="orderFilter" @clear-filter="orderFilter={q:'',status:'',attention:''};load()" v-else-if="route==='/orders'" :rows="items" :loading="loading" @order="showOrder" @refresh="load"/>
<template v-else-if="route==='/wallet'"><div class="page-heading"><div><span class="eyebrow">YOUR MONEY, MADE CLEAR</span><h1>资金中心</h1><p>所有业务共用余额，按业务查看每笔变动。</p></div><button class="btn secondary" @click="load">刷新账本</button></div><div class="wallet-layout"><section class="balance-card"><span>账户可用金额</span><h2>{{cash(Number(data.balance||0)-Number(data.frozen||0))}}<small>积分</small></h2><div class="balance-bottom"><div><small>已冻结</small><b>{{cash(data.frozen)}} 积分</b></div><ShieldCheck :size="34"/></div></section><section class="panel redeem-panel"><div><span class="icon-tile"><Gift :size="21"/></span><h2>兑换码充值</h2><p>输入兑换码充值到统一余额，注册、订阅和代退均可使用。</p></div><form @submit.prevent="submit(async()=>{const r=await api('/wallet/redeem','POST',{code:redeem});notify('已入账 '+cash(r.amount)+' 积分');redeem='';await load();emit('refresh')})"><input v-model="redeem" required placeholder="请输入兑换码" aria-label="兑换码"/><button class="btn primary" :disabled="busy">兑换<ArrowRight :size="16"/></button></form></section><section class="panel topup-panel"><span class="eyebrow">ADD FUNDS</span><h2>充值申请</h2><p>人工核实到账后入账。<br/>请先联系运营确认充值方式。</p><button class="btn secondary" @click="modal='topup'">提交申请<Plus :size="16"/></button></section></div><div class="section-heading"><div class="tabs"><button :class="{active:tab==='ledger'}" @click="tab='ledger'">资金流水</button><button :class="{active:tab==='topups'}" @click="tab='topups'">充值记录</button></div><span class="muted small">金额单位：积分</span></div><template v-if="tab==='ledger'"><LedgerTable business="shared" :rows="(data.ledger||[]).filter((row:Row)=>row.business==='shared')" :loading="loading" @order="showOrder"/><div class="section-heading wallet-business-heading"><div><h2>业务流水</h2><p class="muted small">按订单所属业务查看冻结、结算和退款。</p></div></div><BusinessTabs :model-value="business==='subscription'?'subscription':business==='refund'?'refund':'registration'" @update:model-value="emit('business',$event)"/><LedgerTable :key="business" :business="business||'registration'" :rows="(data.ledger||[]).filter((row:Row)=>row.business===(business||'registration'))" :loading="loading" @order="showOrder"/></template><RechargeTable v-else :rows="data.recharges||[]" :loading="loading" :busy="busy" @cancel="id=>submit(async()=>{await api('/topups/'+id+'/cancel','POST',{});await load();notify('已撤回')})"/></template>
<template v-else-if="route==='/keys'"><div class="page-heading"><div><span class="eyebrow">BUILT TO CONNECT</span><h1>开发接入</h1><p>一个密钥接入注册、订阅与代退，共用账户与余额。</p></div><button class="btn primary" @click="modal='key'"><Plus :size="17"/>新建访问密钥</button></div><div class="callout"><ShieldCheck :size="18"/>可随时复制有效密钥、修改用途名称。密钥仅用于客户业务接口。</div><div class="panel"><DataTable :rows="items" :columns="[{key:'name',label:'用途名称'},{key:'prefix',label:'密钥标识'},{key:'status',label:'状态'},{key:'last_used',label:'最近使用'},{key:'action',label:'操作'}]"><template #prefix="{row}"><code>{{row.prefix}}</code></template><template #status="{row}"><span class="badge" :class="row.revoked?'disabled':'active'">{{row.revoked?'已撤销':'有效'}}</span></template><template #last_used="{row}">{{date(row.last_used)}}</template><template #action="{row}"><div class="key-actions"><button v-if="!row.revoked" class="text-btn" :disabled="busy||!row.copyable" :title="row.copyable?'复制完整密钥':'原密钥下次有效调用后可复制'" @click="submit(async()=>{const v=await api('/keys/'+row.id+'/reveal','POST',{});await copy(v.key)})">{{row.copyable?'复制':'待再次使用'}}</button><button class="text-btn" @click="detail=row;keyName=row.name;modal='renameKey'">改名</button><button v-if="!row.revoked" class="text-btn danger-text" @click="detail=row;modal='revoke'">撤销</button></div></template></DataTable></div><section class="panel docs-panel"><div class="panel-heading"><h2>开发者文档</h2><a v-if="enabled('docs')" href="/docs" target="_blank" rel="noopener noreferrer" class="btn primary">查看完整 API 文档<ArrowUpRight :size="16"/></a></div><p>包含注册下单、OAuth、账号交付与导出、订阅办理、结账链接、关闭自动续费、代退申请与进度查询，以及订单、资金和账户接口，提供调用示例与统一 OpenAPI 下载。</p><p class="muted">同一个访问密钥用于注册、订阅与代退，可在这里统一撤销。</p></section></template>
<PartnerPage v-else-if="route==='/invites'" :user="user"/>
<template v-else-if="route==='/renewal'"><div class="page-heading"><div><span class="eyebrow">SUBSCRIPTION SETTINGS</span><h1>续费管理</h1><p>单独关闭已有订阅的自动续费，或查看订阅办理中的续费设置。</p></div></div><RenewalPage/><h2 class="renewal-orders-title">订阅办理记录</h2><div class="panel"><DataTable :rows="items.filter(x=>x.workflow==='subscription')" :columns="[{key:'email',label:'订阅账号'},{key:'product_name',label:'方案'},{key:'renewal',label:'续费设置'},{key:'action',label:'详情'}]"><template #renewal="{row}">{{({kept:'保留自动续费',disabled:'已关闭自动续费',pending:'等待处理',review:'待核实',not_started:'尚未开始'} as Row)[row.renewal]||row.renewal}}</template><template #action="{row}"><button class="text-btn" @click="showOrder(row)">查看进度</button></template></DataTable></div></template>
<ProfilePage v-else-if="route==='/profile'" :user="user" @refresh="emit('refresh')" @logout="emit('logout')" @order="showOrder"/>
<div v-else class="empty"><h2>页面不存在</h2><a href="#/home">返回工作台</a></div>
<Modal v-if="modal" :title="({order:'订单详情',terms:'服务约定',topup:'提交充值申请',key:'创建访问密钥',revoke:'撤销访问密钥',renameKey:'修改用途名称'} as Row)[modal]||'详情'" :wide="modal==='order'" @close="modal='';newKey=''">
<template v-if="modal==='order'"><p class="live-status" role="status">{{orderConnection==='live'?'进度实时同步':orderConnection==='connecting'?'正在连接实时进度…':'实时连接中断，正在重连…'}} <button class="text-btn" @click="updateDetail">刷新</button></p><div class="detail-title"><div><h3>{{detail.order?.product_name}}</h3><p>{{detail.order?.email}}</p><small class="mono">{{detail.order?.id}}</small></div><span class="badge order-status" :class="orderTone(detail.order)">{{orderLabel(detail.order)}}</span></div><ProgressTrack :status="detail.order?.status" :payment-state="detail.payment?.state" :workflow="detail.order?.workflow" :renewal="detail.order?.renewal" :activation="detail.order?.activation" :progress-stage="detail.order?.progress_stage"/><CheckoutResult v-if="detail.order?.workflow!=='subscription'" :checkout="detail.checkout" :payment-state="detail.payment?.state"/><PaymentPanel v-if="detail.order?.workflow==='subscription'||detail.payment?.state" :order="detail.order" :payment="detail.payment" :checkout="detail.checkout" :support-enabled="enabled('support')" :renewal-enabled="enabled('renewal')" @refresh="showOrder(detail.order);emit('refresh')"/><p v-if="detailRefreshError" class="muted">{{detailRefreshError}}</p><div class="callout" v-if="detail.order?.status==='draft'">方案已保存。本订单尚未生成结账链接或发起付款。</div><button v-if="detail.order?.workflow!=='subscription'&&!detail.payment?.state&&['draft','queued','awaiting_payment'].includes(detail.order?.status)" class="btn secondary" :disabled="busy" @click="cancelOrder(detail.order.id)">撤回此方案</button></template>
<div v-else-if="modal==='terms'" class="pre-wrap">{{pub.site.terms}}</div>
<form v-else-if="modal==='topup'" @submit.prevent="submit(async()=>{await api('/topups','POST',{amount:Math.round(topupAmount*100),proof});notify('申请已提交，等待运营核实到账');modal='';proof='';await load()})"><div class="callout">此处只提交入账申请，不发起扣款。请先与运营确认收款方式并完成转账，勿在备注填写银行卡或密码。</div><label>申请金额（积分）<input v-model.number="topupAmount" type="number" required min="1" step="0.01"/></label><label>转账凭据 / 备注<textarea v-model="proof" maxlength="500" placeholder="时间、渠道、交易编号等核对信息"></textarea></label><button class="btn primary full" :disabled="busy">提交审核</button></form>
<template v-else-if="modal==='renameKey'"><form @submit.prevent="submit(async()=>{await api('/keys/'+detail.id,'PATCH',{name:keyName});modal='';keyName='';await load();notify('用途名称已修改')})"><label>用途名称<input v-model="keyName" required maxlength="80" autocomplete="off"/></label><button class="btn primary full" :disabled="busy">保存名称</button></form></template>
<template v-else-if="modal==='key'"><form v-if="!newKey" @submit.prevent="submit(async()=>{const v=await api('/keys','POST',{name:keyName});newKey=v.key;keyName='';await load()})"><label>用途名称<input v-model="keyName" required maxlength="80" placeholder="例如：生产业务系统"/></label><button class="btn primary full" :disabled="busy">生成密钥</button></form><div v-else><div class="alert">请妥善保管密钥。关闭后仍可在密钥列表中复制。</div><pre class="secret-display">{{newKey}}</pre><button class="btn primary" @click="action(()=>copy(newKey))"><Copy :size="16"/>复制密钥</button></div></template>
<template v-else-if="modal==='revoke'"><p>撤销「{{detail.name}}」后，使用它的请求将立即失效。</p><button class="btn danger" :disabled="busy" @click="submit(async()=>{await api('/keys/'+detail.id,'DELETE');modal='';await load();notify('密钥已撤销')})">确认撤销</button></template></Modal></div></template>

